<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { Film,Refresh,Search } from '@element-plus/icons-vue'
import { request } from '../api/client'
interface Media{id:string;source:string;title:string;year:string;mediaType:string;overview:string;poster:string;filePath?:string;state?:string;season?:number;episode?:number}
const source=ref('managed'),query=ref(''),kind=ref(''),items=ref<Media[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),detail=ref<Media|null>(null),dialog=ref(false),broken=reactive(new Set<string>())
let serial=0
async function load(){const sequence=++serial;loading.value=true;error.value='';try{const out=await request<{items:Media[];total:number}>(`/media/library?source=${source.value}&q=${encodeURIComponent(query.value)}&mediaType=${kind.value}&page=${page.value}&pageSize=24`);if(sequence!==serial)return;items.value=out.items;total.value=out.total;broken.clear()}catch(e){if(sequence===serial){items.value=[];total.value=0;error.value=e instanceof Error?e.message:'媒体库暂不可用'}}finally{if(sequence===serial)loading.value=false}}
function search(){page.value=1;void load()}
function show(item:Media){detail.value=item;dialog.value=true}
onMounted(load)
</script>
<template>
 <section class="page-heading"><div><h1>媒体库</h1><p>查看本程序入库的媒体，以及 Emby 已有媒体库内容；不会修改播放地址或自动整理现有文件。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新媒体库</el-button></section>
 <section class="panel catalog-toolbar"><el-radio-group v-model="source" aria-label="媒体库来源" @change="search"><el-radio-button value="managed">本程序入库</el-radio-button><el-radio-button value="emby">Emby 媒体库</el-radio-button></el-radio-group><el-select v-model="kind" aria-label="媒体类型筛选" placeholder="全部类型" @change="search"><el-option label="全部类型" value=""/><el-option label="电影" value="movie"/><el-option label="电视剧" value="series"/></el-select><el-input v-model="query" aria-label="搜索媒体标题" placeholder="搜索媒体标题" clearable @keyup.enter="search"/><el-button :icon="Search" @click="search">搜索</el-button></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><p class="catalog-count">{{source==='emby'?'Emby 媒体库':'本程序媒体库'}} · {{total}} 项</p>
 <section v-loading="loading" class="media-grid" aria-label="媒体库内容"><button v-for="item in items" :key="item.source+item.id" class="media-card" @click="show(item)"><div class="poster"><img v-if="item.poster&&!broken.has(item.id)" :src="item.poster" :alt="`${item.title} 海报`" loading="lazy" @error="broken.add(item.id)"/><div v-else class="poster-placeholder"><Film aria-hidden="true"/><span>暂无海报</span></div></div><div class="media-copy"><h2>{{item.title}}</h2><p>{{item.year||'年份未知'}} · {{item.mediaType==='movie'?'电影':item.mediaType==='series'?'电视剧':'媒体'}}<span v-if="item.season!==undefined"> · S{{String(item.season).padStart(2,'0')}}</span><span v-if="item.episode!==undefined">E{{String(item.episode).padStart(2,'0')}}</span></p><small v-if="item.state&&item.state!=='emby'">{{({present:'文件在库',trashed:'已移入回收目录',missing:'文件缺失',suspected_missing:'待对账'})[item.state]??item.state}}</small></div></button></section>
 <el-empty v-if="!loading&&!items.length&&!error" description="当前来源没有符合条件的媒体"><RouterLink v-if="source==='managed'" to="/cloudStorage">扫描并确认云盘媒体</RouterLink><RouterLink v-else to="/integrations?kind=emby">检查 Emby 独立配置</RouterLink></el-empty>
 <p v-if="error&&source==='emby'" class="field-hint">请在 <RouterLink to="/integrations?kind=emby">Emby 独立配置</RouterLink> 填写媒体库 API Key 并启用。凭据只由后端使用，不加入海报URL或浏览器请求。</p>
 <el-pagination v-model:current-page="page" :page-size="24" :total="total" layout="prev,pager,next,total" @current-change="load"/>
 <el-dialog v-model="dialog" :title="detail?.title" width="min(700px,94vw)" class="media-details"><p>{{detail?.year||'年份未知'}} · {{detail?.mediaType==='movie'?'电影':'电视剧 / 媒体'}}</p><p class="overview">{{detail?.overview||'暂无简介'}}</p><div v-if="detail?.filePath"><h3>云盘文件位置</h3><code>{{detail.filePath}}</code><p class="field-hint">重命名或分类移动请使用文件管理；播放仍使用固定STRM解析链接。</p><RouterLink to="/files">打开文件管理</RouterLink></div><template #footer><el-button @click="dialog=false">关闭</el-button></template></el-dialog>
</template>
<style scoped>
.catalog-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-bottom:20px}.catalog-toolbar .el-select{width:140px}.catalog-toolbar .el-input{flex:1;min-width:180px}.catalog-count{color:var(--muted);margin:20px 0}.media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:24px;margin-bottom:24px;min-height:160px}.media-card{border:1px solid var(--border);border-radius:8px;background:var(--panel-bg,#fff);padding:0;text-align:left;cursor:pointer;overflow:hidden;color:var(--text);transition:border-color .16s}.media-card:hover{border-color:var(--el-color-primary)}.media-card:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:3px}.poster{aspect-ratio:2/3;background:var(--el-color-primary-light-9)}.poster img{width:100%;height:100%;object-fit:cover}.poster-placeholder{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;height:100%;color:var(--muted)}.poster-placeholder svg{width:44px;height:44px}.media-copy{padding:14px}.media-copy h2{font-size:16px;line-height:1.5;margin:0 0 8px;overflow-wrap:anywhere}.media-copy p,.media-copy small{font-size:13px;line-height:1.6;color:var(--muted);margin:0}.el-pagination{overflow:auto}.overview{line-height:1.8;white-space:pre-wrap}.media-details code{overflow-wrap:anywhere}.media-details h3{font-size:15px}@media(max-width:680px){.catalog-toolbar .el-input{width:100%}.media-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.media-copy{padding:12px}}
</style>
